const resp = $json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
const text = (textBlock && textBlock.text) || '';
let parsed;
try {
  const cleaned = text.trim().replace(/^```json\n?/, '').replace(/```$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { problem: '', root_cause: '', proposed_prompt_change: '', new_examples: [], expected_benefit: '', risk: '', confidence: 0 };
}
return [{ json: parsed }];

const resp = $json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
const text = (textBlock && textBlock.text) || '';
return [{ json: { candidate_prompt_text: text.trim() } }];

const cases = $('Get Golden Eval Cases').all().map(i => i.json);
const responses = $input.all().map(i => i.json);
const combined = cases.map((c, idx) => {
  const resp = responses[idx] || {};
  const text = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
  const inputTokens = (resp.usage && resp.usage.prompt_tokens) || 0;
  const outputTokens = (resp.usage && resp.usage.completion_tokens) || 0;
  return { ...c, actual_answer: text, input_tokens: inputTokens, output_tokens: outputTokens };
});
return [{ json: { combined } }];

