const judgeResults = $('Parse Judge Output').first().json.results || [];
const passCount = judgeResults.filter(r => r.pass).length;
const totalCount = judgeResults.length;
const passRate = totalCount > 0 ? passCount / totalCount : 0;

const criticalFail = judgeResults.some(r => r.category === 'sensitive_data' && r.severity === 'critical' && !r.pass);
const autoReject = passRate < 0.90 || criticalFail;

const evaluatorOut = $('Parse Evaluator Output').first().json;
const rationale = 'Problem: ' + evaluatorOut.problem + '\nRoot cause: ' + evaluatorOut.root_cause + '\nExpected benefit: ' + evaluatorOut.expected_benefit + '\nRisk: ' + evaluatorOut.risk + '\nConfidence: ' + evaluatorOut.confidence;

const pricingRows = $('Get Model Pricing').all().map(i => i.json);
const nanoPricing = pricingRows.find(r => r.model_name === 'gpt-5.4-nano') || {};
const sonnetPricing = pricingRows.find(r => r.model_name === 'claude-sonnet-5') || {};
const nanoIn = Number(nanoPricing.input_price_per_1m_tokens) || 0;
const nanoOut = Number(nanoPricing.output_price_per_1m_tokens) || 0;
const sonnetIn = Number(sonnetPricing.input_price_per_1m_tokens) || 0;
const sonnetOut = Number(sonnetPricing.output_price_per_1m_tokens) || 0;

const evalCall = $('Call Evaluator').first().json;
const evalUsage = evalCall.usage || {};
const synthCall = $('Synthesize Candidate Prompt').first().json;
const synthUsage = synthCall.usage || {};

const candidateAnswers = $('Collect Candidate Answers').first().json.combined || [];
const candidateInTokens = candidateAnswers.reduce((s, c) => s + (c.input_tokens || 0), 0);
const candidateOutTokens = candidateAnswers.reduce((s, c) => s + (c.output_tokens || 0), 0);

const judgeOut = $('Parse Judge Output').first().json;

const sonnetCost = ((evalUsage.input_tokens || 0) + (synthUsage.input_tokens || 0)) / 1e6 * sonnetIn
  + ((evalUsage.output_tokens || 0) + (synthUsage.output_tokens || 0)) / 1e6 * sonnetOut;
const nanoCost = (candidateInTokens + (judgeOut.input_tokens || 0)) / 1e6 * nanoIn
  + (candidateOutTokens + (judgeOut.output_tokens || 0)) / 1e6 * nanoOut;
const totalCost = sonnetCost + nanoCost;

const flagged = $('Aggregate Flagged Interactions').first().json.flagged || [];
const sourceInteractionIds = flagged.map(f => f.id);

return [{ json: {
  pass_rate: passRate,
  auto_reject: autoReject,
  status: autoReject ? 'rejected' : 'pending',
  rationale,
  evaluation_cost_usd: totalCost,
  source_interaction_ids: sourceInteractionIds,
  new_examples: evaluatorOut.new_examples || [],
} }];

